#!/usr/bin/env bash
# Generates a SYNTHETIC token-shaped string at runtime so that secret scanning has something to find
# WITHOUT committing a token-shaped string to Git (GitHub push protection would reject it, and it is
# bad practice to commit one even when fake). The output file is gitignored.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TARGET="$ROOT/devsecops/app-or-lab-target/leaked_config.py"

PREFIX="ghp_"
BODY="0123456789abcdefghijklmnopqrstuvwxyz"   # obviously sequential/synthetic, 36 chars

cat > "$TARGET" <<EOF
# SYNTHETIC LAB VALUE generated by scripts/plant_demo_secret.sh - not a real credential.
# Gitignored. Exists only so Trivy secret scanning has a deliberate finding in the lab image.
GITHUB_TOKEN = "${PREFIX}${BODY}"
EOF
echo "Planted synthetic secret at: ${TARGET#$ROOT/}"
